//! Shared by the integration tests that replay the House patch fixture
//! (`house_patches.rs`, `no_alloc.rs`, `perf.rs`).
//!
//! `fixtures/house_patches.txt` is generated by
//! `app/src/state/patches.fixture.test.ts` from `app/src/state/housePatches.ts`
//! (`UPDATE_FIXTURES=1 npx vitest run app/src/state/patches.fixture.test.ts`).
//! Per patch: `patch <name>`, `phrase <chord4|chord5|bass|lead>`, then the
//! exact commands the UI sends to add a synth track (slot 0) holding it, one
//! `op a b c d` per line.
#![allow(dead_code)]

pub const HOUSE_FIXTURE: &str = include_str!("../fixtures/house_patches.txt");

/// What the level, peak and CPU tests play on a patch (plan 11 *The House set*).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Phrase {
    /// C4 E4 G4 B4 (keys and stabs).
    Chord4,
    /// C3 G3 C4 E4 B4 (pads).
    Chord5,
    /// C2, then C3 (mono).
    Bass,
    /// C4 (mono).
    Lead,
}

impl Phrase {
    /// The phrase's notes as successive chords (a mono phrase is one note per
    /// step; a poly phrase is one chord).
    pub fn steps(self) -> &'static [&'static [u8]] {
        match self {
            Phrase::Chord4 => &[&[60, 64, 67, 71]],
            Phrase::Chord5 => &[&[48, 55, 60, 64, 71]],
            Phrase::Bass => &[&[36], &[48]],
            Phrase::Lead => &[&[60]],
        }
    }
    pub fn mono(self) -> bool {
        matches!(self, Phrase::Bass | Phrase::Lead)
    }
}

pub struct HousePatch {
    pub name: String,
    pub phrase: Phrase,
    pub cmds: Vec<[f64; 5]>,
}

/// Every patch of the fixture, in order. Panics on a patch without a
/// `phrase` line (a stale or hand-edited fixture), rather than guessing one.
pub fn house_patches() -> Vec<HousePatch> {
    let mut out: Vec<(String, Option<Phrase>, Vec<[f64; 5]>)> = Vec::new();
    for line in HOUSE_FIXTURE.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        if let Some(name) = line.strip_prefix("patch ") {
            out.push((name.to_string(), None, Vec::new()));
            continue;
        }
        let last = out.last_mut().expect("line before the first patch");
        if let Some(p) = line.strip_prefix("phrase ") {
            assert!(last.1.is_none(), "patch {:?} has two phrase lines", last.0);
            last.1 = Some(match p {
                "chord4" => Phrase::Chord4,
                "chord5" => Phrase::Chord5,
                "bass" => Phrase::Bass,
                "lead" => Phrase::Lead,
                other => panic!("unknown phrase {other:?}"),
            });
            continue;
        }
        let nums: Vec<f64> = line.split_whitespace().map(|x| x.parse().expect("number")).collect();
        assert_eq!(nums.len(), 5, "bad fixture line {line:?}");
        last.2.push([nums[0], nums[1], nums[2], nums[3], nums[4]]);
    }
    out.into_iter()
        .map(|(name, phrase, cmds)| {
            let phrase = phrase.unwrap_or_else(|| panic!("house patch {name:?} has no phrase line in the fixture"));
            HousePatch { name, phrase, cmds }
        })
        .collect()
}
